#!/usr/bin/env python3
"""v44 : moteur de regroupement des campagnes par produit (Performance). Crée 2 fichiers neufs, n'en modifie aucun.
Usage : python3 apply-v44.py [--check]"""
import sys, pathlib, json, hashlib
CHECK = "--check" in sys.argv
FILES = json.loads(r'''{"src/lib/performance/campaign-groups.ts": "// Regroupe les campagnes Meta par produit et choisit la bonne référence de comparaison.\n// Un même compte publicitaire sert souvent plusieurs produits (carport, pompe à chaleur…) :\n// comparer une campagne à la moyenne de tout le compte n'a pas de sens. On la compare\n// à son produit, avec le même objectif ; s'il n'y a pas assez de campagnes dans le produit,\n// on revient au même objectif sur le même compte, et on le dit.\n// Aucune valeur propre à un client n'est codée ici : tout vient des noms de campagnes et de pubs.\n\nexport type ObjectiveKind = \"leads\" | \"sales\" | \"traffic\" | \"awareness\" | \"engagement\";\n\nexport const OBJECTIVE_LABELS: Record<ObjectiveKind, { tab: string; result: string; one: string; many: string; cost: string }> = {\n  leads: { tab: \"Leads\", result: \"Leads reçus\", one: \"lead\", many: \"leads\", cost: \"Coût par lead\" },\n  sales: { tab: \"Ventes\", result: \"Achats\", one: \"achat\", many: \"achats\", cost: \"Coût par achat\" },\n  traffic: { tab: \"Trafic\", result: \"Clics vers le site\", one: \"clic\", many: \"clics\", cost: \"Coût par clic\" },\n  awareness: { tab: \"Notoriété\", result: \"Personnes touchées\", one: \"personne\", many: \"personnes\", cost: \"Coût pour 1 000 personnes\" },\n  engagement: { tab: \"Messages et interactions\", result: \"Interactions\", one: \"interaction\", many: \"interactions\", cost: \"Coût par interaction\" },\n};\n\n/** Objectif Meta (ancien ou nouveau nom) → famille affichée. */\nexport function objectiveKind(objective?: string | null): ObjectiveKind {\n  const o = String(objective ?? \"\").toUpperCase();\n  if (o.includes(\"LEAD\")) return \"leads\";\n  if (/SALES|CONVERSION|CATALOG|PURCHASE|STORE_VISIT|PRODUCT/.test(o)) return \"sales\";\n  if (/AWARENESS|REACH|BRAND|VIDEO_VIEW|THRUPLAY/.test(o)) return \"awareness\";\n  if (/ENGAGEMENT|MESSAGE|POST|PAGE_LIKE|EVENT|APP/.test(o)) return \"engagement\";\n  return \"traffic\";\n}\n\n/** Mots qui décrivent la façon de faire la pub, pas le produit : ignorés pour regrouper. */\nconst NOISE = new Set([\n  \"campagne\", \"campagnes\", \"campaign\", \"pub\", \"pubs\", \"publicite\", \"ads\", \"ad\", \"annonce\",\n  \"lead\", \"leads\", \"vente\", \"ventes\", \"sales\", \"conversion\", \"conversions\", \"trafic\", \"traffic\", \"notoriete\", \"awareness\",\n  \"engagement\", \"messages\", \"message\", \"formulaire\", \"form\", \"instant\", \"instantane\",\n  \"test\", \"tests\", \"abtest\", \"copie\", \"copy\", \"nouveau\", \"nouvelle\", \"new\", \"v\", \"version\",\n  \"fr\", \"france\", \"be\", \"ch\", \"lu\", \"ca\", \"national\", \"local\", \"region\",\n  \"broad\", \"large\", \"lal\", \"lookalike\", \"similaire\", \"retargeting\", \"relance\", \"remarketing\", \"visiteurs\", \"audience\", \"audiences\",\n  \"interets\", \"interet\", \"chaud\", \"froid\", \"cold\", \"warm\", \"hot\", \"tof\", \"mof\", \"bof\",\n  \"cbo\", \"abo\", \"advantage\", \"asc\", \"adv\", \"plus\",\n  \"hiver\", \"ete\", \"printemps\", \"automne\", \"noel\", \"blackfriday\", \"black\", \"friday\", \"soldes\", \"promo\", \"promotion\", \"rentree\",\n  \"janvier\", \"fevrier\", \"mars\", \"avril\", \"mai\", \"juin\", \"juillet\", \"aout\", \"septembre\", \"octobre\", \"novembre\", \"decembre\",\n  \"ugc\", \"video\", \"videos\", \"image\", \"images\", \"carrousel\", \"carousel\", \"story\", \"stories\", \"reels\", \"reel\", \"feed\",\n  \"meta\", \"facebook\", \"instagram\", \"fb\", \"ig\", \"growthity\",\n  \"de\", \"du\", \"des\", \"la\", \"le\", \"les\", \"l\", \"d\", \"et\", \"a\", \"au\", \"aux\", \"pour\", \"en\", \"sur\", \"avec\", \"sans\", \"un\", \"une\",\n  \"the\", \"and\", \"for\", \"of\", \"with\",\n]);\n\nfunction fold(s: string) {\n  return s.normalize(\"NFD\").replace(/[̀-ͯ]/g, \"\").toLowerCase();\n}\n\n/** Mots significatifs d'un nom, dans l'ordre, avec leur forme d'origine pour l'affichage. */\nexport function productTokens(name: string): Array<{ key: string; label: string }> {\n  const out: Array<{ key: string; label: string }> = [];\n  for (const raw of String(name ?? \"\").split(/[^\\p{L}\\p{N}]+/u)) {\n    if (!raw) continue;\n    const key = fold(raw);\n    if (key.length < 2 || NOISE.has(key) || /^\\d+$/.test(key) || /^v\\d+$/.test(key) || /^(19|20)\\d\\d/.test(key)) continue;\n    // Pluriel simple : « carports » et « carport » sont le même produit.\n    out.push({ key: key.length > 4 && key.endsWith(\"s\") ? key.slice(0, -1) : key, label: raw });\n  }\n  return out;\n}\n\nexport type CampaignInput = {\n  id: string;\n  name: string;\n  objective?: string | null;\n  accountId?: string | null;\n  /** Noms des pubs de la campagne, s'ils sont connus : ils aident à reconnaître le produit. */\n  adNames?: string[];\n  spend: number;\n  results: number;\n  revenue?: number;\n};\n\nexport type ManualGroup = { id: string; name: string; campaignIds: string[] };\n\nexport type ProductGroup = {\n  id: string;\n  name: string;\n  /** \"manuel\" : groupe créé par le client ; \"auto\" : reconnu d'après les noms. */\n  source: \"manuel\" | \"auto\";\n  campaignIds: string[];\n};\n\n/** Les 2 premiers mots significatifs du nom de la campagne, complétés par le mot le plus fréquent de ses pubs. */\nfunction signature(c: CampaignInput): string[] {\n  const own = productTokens(c.name).map((t) => t.key);\n  const counts = new Map<string, number>();\n  for (const ad of c.adNames ?? []) for (const t of new Set(productTokens(ad).map((x) => x.key))) counts.set(t, (counts.get(t) ?? 0) + 1);\n  const adTop = [...counts.entries()].filter(([, n]) => n >= 2).sort((a, b) => b[1] - a[1]).map(([k]) => k);\n  return [...new Set([...own.slice(0, 2), ...adTop.slice(0, 1)])];\n}\n\n/**\n * Regroupe les campagnes par produit.\n * - Les groupes créés à la main passent toujours en premier.\n * - Deux campagnes vont ensemble si elles commencent par le même mot de produit\n *   (« Carport · Hiver » et « Carport relance »), ou si la moitié de leurs mots de produit sont communs.\n * - Une campagne dont le nom ne contient aucun mot de produit reste seule, sous son propre nom.\n */\nexport function groupCampaigns(campaigns: CampaignInput[], manual: ManualGroup[] = []): ProductGroup[] {\n  const taken = new Set<string>();\n  const groups: ProductGroup[] = [];\n  for (const g of manual) {\n    const ids = g.campaignIds.filter((id) => campaigns.some((c) => c.id === id) && !taken.has(id));\n    ids.forEach((id) => taken.add(id));\n    if (ids.length) groups.push({ id: `manuel:${g.id}`, name: g.name, source: \"manuel\", campaignIds: ids });\n  }\n  const rest = campaigns.filter((c) => !taken.has(c.id));\n  const sig = new Map(rest.map((c) => [c.id, signature(c)]));\n  const parent = new Map(rest.map((c) => [c.id, c.id]));\n  const find = (x: string): string => (parent.get(x) === x ? x : find(parent.get(x)!));\n  const join = (a: string, b: string) => { const ra = find(a), rb = find(b); if (ra !== rb) parent.set(rb, ra); };\n  for (let i = 0; i < rest.length; i++) {\n    for (let j = i + 1; j < rest.length; j++) {\n      const a = sig.get(rest[i].id)!, b = sig.get(rest[j].id)!;\n      if (!a.length || !b.length) continue;\n      const common = a.filter((t) => b.includes(t)).length;\n      if (a[0] === b[0] || common / Math.min(a.length, b.length) >= 0.5) join(rest[i].id, rest[j].id);\n    }\n  }\n  const byRoot = new Map<string, CampaignInput[]>();\n  for (const c of rest) byRoot.set(find(c.id), [...(byRoot.get(find(c.id)) ?? []), c]);\n  for (const [root, list] of byRoot) {\n    groups.push({ id: `auto:${root}`, name: groupName(list), source: \"auto\", campaignIds: list.map((c) => c.id) });\n  }\n  return groups;\n}\n\n/** Nom du groupe : les mots de produit communs à toutes ses campagnes, tels qu'écrits par le client. */\nexport function groupName(list: CampaignInput[]): string {\n  const toks = list.map((c) => productTokens(c.name));\n  const first = toks[0] ?? [];\n  const common = first.filter((t) => toks.every((ts) => ts.some((x) => x.key === t.key)));\n  const words = (common.length ? common : first.slice(0, 1)).slice(0, 3).map((t) => t.label);\n  const name = words.join(\" \");\n  if (!name) return list[0]?.name?.trim() || \"Sans nom\";\n  return name.charAt(0).toUpperCase() + name.slice(1);\n}\n\n/** Coût par résultat ; pour les ventes, ventes rapportées pour 1 € dépensé (plus haut = mieux). */\nexport function efficiency(kind: ObjectiveKind, spend: number, results: number, revenue = 0): number | null {\n  if (kind === \"sales\") return spend > 0 && revenue > 0 ? revenue / spend : null;\n  if (results <= 0) return null;\n  return kind === \"awareness\" ? (spend / results) * 1000 : spend / results;\n}\n\nexport type Benchmark = { value: number; basis: \"produit\" | \"compte\"; label: string } | null;\n\n/**\n * Référence d'une campagne : son produit (même objectif) s'il a au moins 2 campagnes avec des résultats,\n * sinon le même objectif sur le même compte publicitaire. Jamais tout le compte, tous objectifs mélangés.\n */\nexport function benchmarkFor(c: CampaignInput, groups: ProductGroup[], all: CampaignInput[]): Benchmark {\n  const kind = objectiveKind(c.objective);\n  const sum = (list: CampaignInput[]) => efficiency(kind, list.reduce((s, x) => s + x.spend, 0), list.reduce((s, x) => s + x.results, 0), list.reduce((s, x) => s + (x.revenue ?? 0), 0));\n  const g = groups.find((x) => x.campaignIds.includes(c.id));\n  const peers = all.filter((x) => g?.campaignIds.includes(x.id) && objectiveKind(x.objective) === kind && (x.results > 0 || (x.revenue ?? 0) > 0));\n  if (g && peers.length >= 2) { const v = sum(peers); if (v != null) return { value: v, basis: \"produit\", label: `tes campagnes ${g.name}` }; }\n  const acct = all.filter((x) => (x.accountId ?? null) === (c.accountId ?? null) && objectiveKind(x.objective) === kind && (x.results > 0 || (x.revenue ?? 0) > 0));\n  if (acct.length >= 2) { const v = sum(acct); if (v != null) return { value: v, basis: \"compte\", label: \"tes autres campagnes du même objectif sur ce compte\" }; }\n  return null;\n}\n\nexport type Verdict = \"meilleure\" | \"normale\" | \"plus_chere\" | \"trop_tot\";\n\n/**\n * Jugement d'une campagne par rapport à sa référence.\n * « trop_tot » tant qu'il n'y a pas assez de données : moins de 3 résultats et moins de 2 fois le coût de référence dépensé.\n */\nexport function verdictFor(c: CampaignInput, bench: Benchmark): Verdict {\n  const kind = objectiveKind(c.objective);\n  const v = efficiency(kind, c.spend, c.results, c.revenue ?? 0);\n  if (!bench) return \"trop_tot\";\n  const enough = c.results >= 3 || (kind !== \"sales\" && c.spend >= bench.value * 2) || (kind === \"sales\" && c.spend >= 50);\n  if (!enough || v == null) return \"trop_tot\";\n  const ratio = kind === \"sales\" ? bench.value / v : v / bench.value; // < 1 = mieux\n  if (ratio <= 0.95) return \"meilleure\";\n  if (ratio >= 1.25) return \"plus_chere\";\n  return \"normale\";\n}\n", "src/lib/performance/campaign-groups.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { benchmarkFor, groupCampaigns, objectiveKind, productTokens, verdictFor, type CampaignInput } from \"./campaign-groups\";\n\nconst C = (id: string, name: string, objective: string, spend: number, results: number, extra: Partial<CampaignInput> = {}): CampaignInput =>\n  ({ id, name, objective, spend, results, accountId: \"act_1\", ...extra });\n\ndescribe(\"objectifs Meta\", () => {\n  it(\"reconnaît les anciens et les nouveaux noms\", () => {\n    expect(objectiveKind(\"OUTCOME_LEADS\")).toBe(\"leads\");\n    expect(objectiveKind(\"LEAD_GENERATION\")).toBe(\"leads\");\n    expect(objectiveKind(\"OUTCOME_SALES\")).toBe(\"sales\");\n    expect(objectiveKind(\"CONVERSIONS\")).toBe(\"sales\");\n    expect(objectiveKind(\"OUTCOME_TRAFFIC\")).toBe(\"traffic\");\n    expect(objectiveKind(\"LINK_CLICKS\")).toBe(\"traffic\");\n    expect(objectiveKind(\"OUTCOME_AWARENESS\")).toBe(\"awareness\");\n    expect(objectiveKind(\"OUTCOME_ENGAGEMENT\")).toBe(\"engagement\");\n  });\n});\n\ndescribe(\"regroupement par produit\", () => {\n  const camps = [\n    C(\"1\", \"Carport · Hiver\", \"OUTCOME_LEADS\", 168.4, 26),\n    C(\"2\", \"Carport relance visiteurs 2026\", \"OUTCOME_LEADS\", 54, 6),\n    C(\"3\", \"Carports - Test V2 broad\", \"OUTCOME_LEADS\", 30, 3),\n    C(\"4\", \"Pompe à chaleur · Aides 2026\", \"OUTCOME_LEADS\", 121.1, 13),\n    C(\"5\", \"Pompe à chaleur témoignages\", \"OUTCOME_LEADS\", 88, 8),\n    C(\"6\", \"Isolation · Prime énergie\", \"OUTCOME_LEADS\", 63.3, 3),\n  ];\n  const groups = groupCampaigns(camps);\n\n  it(\"met ensemble les campagnes du même produit, malgré la saison, le pluriel ou « test »\", () => {\n    const carport = groups.find((g) => g.campaignIds.includes(\"1\"))!;\n    expect(carport.campaignIds.sort()).toEqual([\"1\", \"2\", \"3\"]);\n    expect(carport.name).toBe(\"Carport\");\n    expect(groups.find((g) => g.campaignIds.includes(\"4\"))!.campaignIds.sort()).toEqual([\"4\", \"5\"]);\n    expect(groups.find((g) => g.campaignIds.includes(\"6\"))!.campaignIds).toEqual([\"6\"]);\n  });\n\n  it(\"ignore les mots de méthode (relance, broad, test, saisons, années)\", () => {\n    expect(productTokens(\"Carport relance visiteurs 2026 broad V3\").map((t) => t.key)).toEqual([\"carport\"]);\n  });\n\n  it(\"les groupes créés à la main passent avant\", () => {\n    const g = groupCampaigns(camps, [{ id: \"m1\", name: \"Énergie\", campaignIds: [\"4\", \"6\"] }]);\n    expect(g[0]).toMatchObject({ source: \"manuel\", name: \"Énergie\", campaignIds: [\"4\", \"6\"] });\n    expect(g.find((x) => x.campaignIds.includes(\"5\"))!.campaignIds).toEqual([\"5\"]);\n  });\n\n  it(\"les noms des pubs aident quand la campagne a un nom vague\", () => {\n    const g = groupCampaigns([\n      C(\"a\", \"Carport hiver\", \"OUTCOME_LEADS\", 10, 1),\n      C(\"b\", \"Campagne leads novembre\", \"OUTCOME_LEADS\", 10, 1, { adNames: [\"Carport UGC 1\", \"Carport UGC 2\", \"Carport avis\"] }),\n    ]);\n    expect(g).toHaveLength(1);\n  });\n});\n\ndescribe(\"comparaison au bon groupe\", () => {\n  const camps = [\n    C(\"1\", \"Carport · Hiver\", \"OUTCOME_LEADS\", 168.4, 26),\n    C(\"2\", \"Carport relance\", \"OUTCOME_LEADS\", 54, 6),\n    C(\"4\", \"Pompe à chaleur · Aides\", \"OUTCOME_LEADS\", 121.1, 13),\n    C(\"6\", \"Isolation · Prime\", \"OUTCOME_LEADS\", 63.3, 3),\n    C(\"9\", \"Sérum Éclat · Ventes\", \"OUTCOME_SALES\", 278, 19, { revenue: 980 }),\n  ];\n  const groups = groupCampaigns(camps);\n\n  it(\"compare une campagne Carport aux autres Carport, pas à tout le compte\", () => {\n    const b = benchmarkFor(camps[0], groups, camps)!;\n    expect(b.basis).toBe(\"produit\");\n    expect(b.value).toBeCloseTo((168.4 + 54) / 32, 2);\n    expect(verdictFor(camps[0], b)).toBe(\"meilleure\"); // 6,48 € contre 6,95 € pour Carport\n    expect(verdictFor(camps[1], benchmarkFor(camps[1], groups, camps))).toBe(\"plus_chere\");\n  });\n\n  it(\"un produit seul se compare au même objectif sur le même compte, jamais aux ventes\", () => {\n    const b = benchmarkFor(camps[3], groups, camps)!;\n    expect(b.basis).toBe(\"compte\");\n    expect(b.value).toBeCloseTo((168.4 + 54 + 121.1 + 63.3) / (26 + 6 + 13 + 3), 2);\n    expect(verdictFor(camps[3], b)).toBe(\"plus_chere\");\n  });\n\n  it(\"ne juge pas une campagne qui n'a pas encore assez de données\", () => {\n    const tiny = C(\"t\", \"Carport essai\", \"OUTCOME_LEADS\", 4, 0);\n    const all = [...camps, tiny];\n    expect(verdictFor(tiny, benchmarkFor(tiny, groupCampaigns(all), all))).toBe(\"trop_tot\");\n  });\n});\n"}''')
SHA = {"src/lib/performance/campaign-groups.ts": "0a70112358c1a211", "src/lib/performance/campaign-groups.test.ts": "f404396d067a94af"}
ok = True
for p, c in FILES.items():
    if hashlib.sha256(c.encode()).hexdigest()[:16] != SHA[p]: print("ÉCHEC empreinte", p); ok = False
    if pathlib.Path(p).exists(): print("ÉCHEC : existe déjà", p); ok = False
if ok and not CHECK:
    for p, c in FILES.items():
        pathlib.Path(p).parent.mkdir(parents=True, exist_ok=True); pathlib.Path(p).write_text(c); print("écrit", p, SHA[p])
print("OK" if ok else "ÉCHEC", "(vérification seule)" if CHECK else "")
sys.exit(0 if ok else 1)
